CREATE OR REPLACE FUNCTION public.permissions_bootstrap(_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c record;r record;v text;BEGIN PERFORM public._assert_admin_writer();PERFORM public._assert_reason(_reason);INSERT INTO public.roles(code,name_ar,is_system) VALUES('investor_viewer','مستثمر — عرض مجمع',true) ON CONFLICT DO NOTHING;FOR c IN SELECT * FROM (VALUES('security.roles','إدارة الأدوار والصلاحيات','الإعدادات'),('users.directory','المستخدمون','الإعدادات'),('units.read','الوحدات','الوحدات'),('units.maintenance','الصيانة','الوحدات'),('customers.names','أسماء العملاء','العملاء'),('customers.contacts','بيانات التواصل والهوية','العملاء'),('opportunities.read','عرض الفرص','الفرص'),('opportunities.write','تعديل الفرص','الفرص'),('opportunities.assign','إعادة توزيع الفرص','الفرص'),('bookings.hold','الحجز المؤقت','الحجوزات'),('contracts.draft','مسودات العقود','العقود'),('finance.read','بيانات المدفوعات','المالية'),('finance.write','تسجيل والتحقق من الإيصالات','المالية'),('receipts.reverse','اعتماد عكس الإيصال','الموافقات'),('contracts.terminate','اعتماد إنهاء العقد','الموافقات'),('customers.merge','اعتماد الدمج','الموافقات'),('holds.extend','تمديد الحجز','الموافقات'),('ownership.transfer','نقل الملكية','الموافقات'),('dashboard.aggregate','الملخص المجمع','التقارير'),('tenant.records','سجلات المستأجر','المستأجرون')) x(code,name_ar,category) LOOP INSERT INTO public.capabilities(code,name_ar,category) VALUES(c.code,c.name_ar,c.category) ON CONFLICT DO NOTHING;FOR r IN SELECT code FROM public.roles WHERE is_system LOOP v:='none';IF r.code='admin' THEN v:=CASE WHEN c.code IN('receipts.reverse','contracts.terminate','customers.merge','ownership.transfer','holds.extend') THEN 'approve' WHEN c.code IN('units.read','customers.names','opportunities.read','finance.read','dashboard.aggregate','users.directory','customers.contacts') THEN 'view' WHEN c.code='tenant.records' THEN 'own' ELSE 'edit' END;ELSIF r.code='sales_agent' THEN v:=CASE WHEN c.code IN('units.read','customers.names','opportunities.read') THEN 'view' WHEN c.code IN('opportunities.write','customers.contacts','contracts.draft') THEN 'own' WHEN c.code='bookings.hold' THEN 'edit' ELSE 'none' END;ELSIF r.code='leasing_manager' THEN v:=CASE WHEN c.code IN('units.read','customers.names','customers.contacts','opportunities.read','dashboard.aggregate') THEN 'view' WHEN c.code IN('opportunities.write','opportunities.assign','bookings.hold','contracts.draft') THEN 'edit' WHEN c.code IN('ownership.transfer','holds.extend') THEN 'approve' ELSE 'none' END;ELSIF r.code='accountant' THEN v:=CASE WHEN c.code IN('finance.read','customers.names','customers.contacts') THEN 'view' WHEN c.code='finance.write' THEN 'edit' ELSE 'none' END;ELSIF r.code='manager' THEN v:=CASE WHEN c.code IN('units.read','customers.names','opportunities.read','finance.read','dashboard.aggregate') THEN 'view' ELSE 'none' END;ELSIF r.code IN('investor','investor_viewer') AND c.code='dashboard.aggregate' THEN v:='view';ELSIF r.code='control' THEN v:=CASE WHEN c.code='units.read' THEN 'view' WHEN c.code='units.maintenance' THEN 'edit' ELSE 'none' END;ELSIF r.code='tenant' AND c.code='tenant.records' THEN v:='own';END IF;INSERT INTO public.role_permissions(role,capability,level,updated_by) VALUES(r.code,c.code,v,auth.uid()) ON CONFLICT DO NOTHING;END LOOP;END LOOP;PERFORM public._safety_audit('PERMISSIONS_BOOTSTRAP','role_permissions','initial',NULL,jsonb_build_object('roles',(SELECT count(*) FROM public.roles)),_reason);END $$;
CREATE OR REPLACE FUNCTION public.admin_save_role(_code text,_name text,_description text,_active boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldrow jsonb;BEGIN IF NOT public.has_permission('security.roles','edit') THEN RAISE EXCEPTION 'إدارة الأدوار للأدمن فقط';END IF;PERFORM public._assert_reason(_reason);IF _code !~ '^[a-z][a-z0-9_]{2,63}$' OR char_length(btrim(_name)) NOT BETWEEN 2 AND 100 OR char_length(_description)>1000 THEN RAISE EXCEPTION 'بيانات الدور غير صالحة';END IF;SELECT to_jsonb(r) INTO oldrow FROM public.roles r WHERE code=_code FOR UPDATE;IF _code='admin' AND NOT _active THEN RAISE EXCEPTION 'لا يمكن إيقاف دور الأدمن';END IF;IF NOT _active AND EXISTS(SELECT 1 FROM public.user_role_assignments WHERE role=_code AND is_active) THEN RAISE EXCEPTION 'أعد تعيين المستخدمين المرتبطين قبل إيقاف الدور';END IF;INSERT INTO public.roles(code,name_ar,description,is_active) VALUES(_code,btrim(_name),_description,_active) ON CONFLICT(code) DO UPDATE SET name_ar=excluded.name_ar,description=excluded.description,is_active=excluded.is_active,updated_at=now(),retired_by=CASE WHEN NOT _active THEN auth.uid() ELSE NULL END,retired_reason=CASE WHEN NOT _active THEN _reason ELSE NULL END;INSERT INTO public.role_permissions(role,capability,level) SELECT _code,code,'none' FROM public.capabilities ON CONFLICT DO NOTHING;PERFORM public._safety_audit('ROLE_SAVED','roles',_code,oldrow,(SELECT to_jsonb(r) FROM public.roles r WHERE code=_code),_reason);END $$;
CREATE OR REPLACE FUNCTION public.admin_set_role_permission(_role text,_capability text,_level text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldrow jsonb;BEGIN IF NOT public.has_permission('security.roles','edit') THEN RAISE EXCEPTION 'إدارة الصلاحيات للأدمن فقط';END IF;PERFORM public._assert_reason(_reason);IF _level NOT IN('none','view','own','edit','approve') THEN RAISE EXCEPTION 'مستوى غير صالح';END IF;IF _role='admin' AND _capability='security.roles' AND _level<>'edit' THEN RAISE EXCEPTION 'لا يمكن تعطيل إدارة الصلاحيات للأدمن';END IF;IF _role='sales_agent' AND (_capability LIKE 'finance.%' OR _capability IN('receipts.reverse','contracts.terminate','customers.merge')) AND _level<>'none' THEN RAISE EXCEPTION 'بيانات المدفوعات والموافقات الإدارية ممنوعة للمبيعات';END IF;IF _role IN('investor','investor_viewer') AND _capability<>'dashboard.aggregate' AND _level<>'none' THEN RAISE EXCEPTION 'المستثمر عرض مجمع فقط';END IF;IF _role='manager' AND _level IN('edit','approve') THEN RAISE EXCEPTION 'المدير للعرض فقط';END IF;IF _role='control' AND ((_capability NOT IN('units.read','units.maintenance') AND _level<>'none') OR (_capability='units.read' AND _level NOT IN('none','view')) OR (_capability='units.maintenance' AND _level NOT IN('none','view','edit'))) THEN RAISE EXCEPTION 'الكنترول للصيانة فقط';END IF;IF _role='tenant' AND (_capability<>'tenant.records' OR _level NOT IN('none','own')) AND _level<>'none' THEN RAISE EXCEPTION 'المستأجر سجلاته فقط';END IF;IF _capability IN('security.roles','receipts.reverse','contracts.terminate','customers.merge') AND _role<>'admin' AND _level<>'none' THEN RAISE EXCEPTION 'الصلاحية محجوزة للأدمن';END IF;SELECT to_jsonb(p) INTO oldrow FROM public.role_permissions p WHERE role=_role AND capability=_capability FOR UPDATE;IF oldrow IS NULL THEN RAISE EXCEPTION 'دور أو صلاحية غير موجودة';END IF;UPDATE public.role_permissions SET level=_level,updated_at=now(),updated_by=auth.uid() WHERE role=_role AND capability=_capability;PERFORM public._safety_audit('ROLE_PERMISSION_CHANGED','role_permissions',_role||':'||_capability,oldrow,(SELECT to_jsonb(p) FROM public.role_permissions p WHERE role=_role AND capability=_capability),_reason);END $$;
CREATE OR REPLACE FUNCTION public.my_permissions() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('roles',coalesce((SELECT jsonb_agg(a.role) FROM public.user_role_assignments a JOIN public.roles r ON r.code=a.role AND r.is_active WHERE a.user_id=auth.uid() AND a.is_active AND NOT EXISTS(SELECT 1 FROM public.staff_accounts WHERE user_id=auth.uid() AND status='inactive')),'[]'),'permissions',coalesce((SELECT jsonb_agg(jsonb_build_object('capability',c.code,'levels',ARRAY(SELECT l FROM unnest(ARRAY['view','own','edit','approve']) l WHERE public.has_permission(c.code,l)))) FROM public.capabilities c),'[]')) $$;
REVOKE ALL ON FUNCTION public.permissions_bootstrap(text),public.admin_save_role(text,text,text,boolean,text),public.admin_set_role_permission(text,text,text,text),public.my_permissions() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.permissions_bootstrap(text),public.admin_save_role(text,text,text,boolean,text),public.admin_set_role_permission(text,text,text,text),public.my_permissions() TO authenticated;
SELECT to_regprocedure('public.admin_save_role(text,text,text,boolean,text)') IS NOT NULL AS role_writer_ready;